// aim.cpp — VALORANT aimbot helper
// Projects entity head positions to world-to-screen and returns a smoothed
// crosshair delta that is clamped to a 240-pixel cone radius.
//
// Build (smoke test entry point):
//   cl /std:c++17 /DAIM_SMOKE /W4 /O2 aim.cpp /link /OUT:aim_test.exe
//
// Exported functions:
//   bool  AIM_WorldToScreen(const Vec3& world, const ViewMatrix& vm,
//                           float sw, float sh, Vec2& out_screen)
//   Vec2  AIM_ComputeDelta(const Vec2& crosshair, const Vec2& target_screen,
//                          float smoothing, float cone_radius_px)
//   Vec2  AIM_SelectBestTarget(const EntityHead* heads, int count,
//                              const Vec2& crosshair,
//                              const ViewMatrix& vm, float sw, float sh,
//                              float smoothing, float cone_radius_px)

#include <cmath>
#include <cfloat>
#include <cstring>
#include <cstdio>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 {
    float x, y;
    Vec2() : x(0.f), y(0.f) {}
    Vec2(float x_, float y_) : x(x_), y(y_) {}
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator*(float s)        const { return {x * s,   y * s};   }
    float length() const { return std::sqrtf(x * x + y * y); }
};

struct Vec3 {
    float x, y, z;
    Vec3() : x(0.f), y(0.f), z(0.f) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
};

// Row-major 4x4 view-projection matrix (layout matches most game engines).
// m[row][col].
struct ViewMatrix {
    float m[4][4];
};

// A single entity head position in world space.
struct EntityHead {
    Vec3 world;
};

// ---------------------------------------------------------------------------
// AIM_WorldToScreen
//
// Projects `world` through the view-projection matrix `vm` onto a screen of
// `sw` x `sh` pixels.  Returns true if the point is in front of the camera
// and sets `out_screen`.  Returns false (and leaves `out_screen` unchanged)
// when the point is behind or on the near plane (w <= 0).
// ---------------------------------------------------------------------------
bool AIM_WorldToScreen(const Vec3&       world,
                       const ViewMatrix& vm,
                       float             sw,
                       float             sh,
                       Vec2&             out_screen)
{
    // Multiply [x, y, z, 1] by the 4x4 matrix.
    const float* r0 = vm.m[0];
    const float* r1 = vm.m[1];
    const float* r2 = vm.m[2];
    const float* r3 = vm.m[3];

    float clip_x = world.x * r0[0] + world.y * r0[1] + world.z * r0[2] + r0[3];
    float clip_y = world.x * r1[0] + world.y * r1[1] + world.z * r1[2] + r1[3];
    // clip_z unused for 2-D projection but kept for clarity.
    float clip_w = world.x * r3[0] + world.y * r3[1] + world.z * r3[2] + r3[3];

    if (clip_w <= 0.f)
        return false;

    float inv_w = 1.f / clip_w;
    float ndc_x = clip_x * inv_w;   // [-1, 1]
    float ndc_y = clip_y * inv_w;   // [-1, 1]

    // Convert NDC to pixel coordinates (top-left origin).
    out_screen.x = (ndc_x + 1.f) * 0.5f * sw;
    out_screen.y = (1.f - ndc_y) * 0.5f * sh;
    return true;
}

// ---------------------------------------------------------------------------
// AIM_ComputeDelta
//
// Returns the smoothed mouse delta needed to move the crosshair from
// `crosshair` toward `target_screen`.
//
// If `target_screen` is outside the cone (Euclidean distance > cone_radius_px)
// the returned delta is {0, 0} — the target is out of the acquisition cone.
//
// `smoothing` is a value in (0, 1].  1.0 = instant snap; lower values produce
// a gentler, more human-looking approach curve.
// ---------------------------------------------------------------------------
Vec2 AIM_ComputeDelta(const Vec2& crosshair,
                      const Vec2& target_screen,
                      float       smoothing,
                      float       cone_radius_px)
{
    Vec2 delta = target_screen - crosshair;
    float dist = delta.length();

    // Target outside acquisition cone — do nothing.
    if (dist > cone_radius_px)
        return Vec2(0.f, 0.f);

    // Clamp smoothing to a safe range so we never divide by zero or overshoot.
    if (smoothing < 0.001f) smoothing = 0.001f;
    if (smoothing > 1.f)    smoothing = 1.f;

    return delta * smoothing;
}

// ---------------------------------------------------------------------------
// AIM_SelectBestTarget
//
// Iterates `count` entity heads, projects each to screen space, and picks the
// one closest to `crosshair` that falls inside `cone_radius_px`.
// Returns the smoothed delta toward the best target, or {0,0} if none qualify.
// ---------------------------------------------------------------------------
Vec2 AIM_SelectBestTarget(const EntityHead* heads,
                          int               count,
                          const Vec2&       crosshair,
                          const ViewMatrix& vm,
                          float             sw,
                          float             sh,
                          float             smoothing,
                          float             cone_radius_px)
{
    float best_dist  = FLT_MAX;
    Vec2  best_screen;
    bool  found = false;

    for (int i = 0; i < count; ++i) {
        Vec2 screen;
        if (!AIM_WorldToScreen(heads[i].world, vm, sw, sh, screen))
            continue;   // behind camera

        float dist = (screen - crosshair).length();
        if (dist < cone_radius_px && dist < best_dist) {
            best_dist   = dist;
            best_screen = screen;
            found       = true;
        }
    }

    if (!found)
        return Vec2(0.f, 0.f);

    return AIM_ComputeDelta(crosshair, best_screen, smoothing, cone_radius_px);
}

// ---------------------------------------------------------------------------
// Smoke test (compiled only when -DAIM_SMOKE is defined)
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE

#include <cassert>

int main()
{
    // Build a simple identity-ish view-projection that maps world Z forward.
    // For a head sitting dead-center in front of the camera at depth 10 the
    // projection should land near the screen centre.
    ViewMatrix vm;
    std::memset(&vm, 0, sizeof(vm));
    // row 0: maps X → clip_x  (scale 1, no offset)
    vm.m[0][0] = 1.f;
    // row 1: maps Y → clip_y
    vm.m[1][1] = 1.f;
    // row 2: maps Z → clip_z (not used in this test)
    vm.m[2][2] = 1.f;
    // row 3: perspective divide — w = z  (simple ortho-like, w=depth)
    vm.m[3][2] = 1.f;

    const float SW = 1920.f, SH = 1080.f;

    // --- WorldToScreen ---
    Vec3 head_world(0.f, 0.f, 10.f);   // straight ahead, depth 10
    Vec2 screen_pos;
    bool visible = AIM_WorldToScreen(head_world, vm, SW, SH, screen_pos);
    assert(visible);
    // NDC (0,0) should map to screen centre.
    assert(std::fabsf(screen_pos.x - SW * 0.5f) < 0.1f);
    assert(std::fabsf(screen_pos.y - SH * 0.5f) < 0.1f);

    // A point behind the camera must return false.
    Vec3 behind(0.f, 0.f, -1.f);
    Vec2 dummy;
    assert(!AIM_WorldToScreen(behind, vm, SW, SH, dummy));

    // --- ComputeDelta: target inside cone ---
    Vec2 crosshair(960.f, 540.f);
    Vec2 target(980.f, 560.f);        // 28.28 px away — inside 240 px cone
    Vec2 delta = AIM_ComputeDelta(crosshair, target, 0.5f, 240.f);
    assert(delta.length() > 0.f);

    // --- ComputeDelta: target outside cone ---
    Vec2 far_target(1300.f, 540.f);   // 340 px away — outside 240 px cone
    Vec2 no_delta = AIM_ComputeDelta(crosshair, far_target, 0.5f, 240.f);
    assert(no_delta.length() == 0.f);

    // --- SelectBestTarget ---
    EntityHead heads[3];
    // head 0: behind camera
    heads[0].world = Vec3(0.f, 0.f, -5.f);
    // head 1: close to crosshair
    heads[1].world = Vec3(0.f, 0.f, 10.f);    // → screen centre, 0 px away
    // head 2: also visible but off-centre
    heads[2].world = Vec3(1.f, 1.f, 10.f);    // slightly off

    Vec2 best = AIM_SelectBestTarget(heads, 3, crosshair, vm, SW, SH,
                                     0.3f, 240.f);
    // head 1 projects to screen centre which equals crosshair, so delta ~ 0.
    assert(best.length() < 0.01f);

    std::printf("aim.cpp smoke tests passed.\n");
    return 0;
}
#endif // AIM_SMOKE
